CREATE TABLE IF NOT EXISTS admin_users (id INT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS medicament (id INT PRIMARY KEY AUTO_INCREMENT,nom VARCHAR(190) NOT NULL UNIQUE,quantite INTEGER NOT NULL DEFAULT 0 CHECK(quantite>=0),prix DECIMAL(12,2),is_actif INTEGER NOT NULL DEFAULT 1 CHECK(is_actif IN(0,1))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS client_users (id INT PRIMARY KEY AUTO_INCREMENT,nom VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,telephone VARCHAR(30),password VARCHAR(255) NOT NULL,google_id VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS patient_accounts (id INT PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(100) NOT NULL,phone VARCHAR(30),email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS patient_requests (id INT PRIMARY KEY AUTO_INCREMENT,access_token_hash VARCHAR(64) NOT NULL UNIQUE,request_type VARCHAR(30) NOT NULL,patient_id INT, FOREIGN KEY(patient_id) REFERENCES patient_accounts(id),patient_name VARCHAR(100) NOT NULL,phone VARCHAR(30),email VARCHAR(190),status VARCHAR(30) NOT NULL,total_amount DECIMAL(12,2),payment_mode VARCHAR(30),payment_phone VARCHAR(30),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS patient_request_items (id INT PRIMARY KEY AUTO_INCREMENT,request_id INT NOT NULL, FOREIGN KEY(request_id) REFERENCES patient_requests(id),medicament_id INT NOT NULL, FOREIGN KEY(medicament_id) REFERENCES medicament(id),medicament_name VARCHAR(190) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price DECIMAL(12,2),is_available INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pharmacy_settings (id INTEGER PRIMARY KEY,is_on_call INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts (bucket VARCHAR(64) NOT NULL,window_id INTEGER NOT NULL,attempts INTEGER NOT NULL,PRIMARY KEY(bucket,window_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO pharmacy_settings(id,is_on_call) VALUES(1,0);
CREATE TABLE IF NOT EXISTS reservations (id INT PRIMARY KEY AUTO_INCREMENT,reference VARCHAR(16) NOT NULL UNIQUE,client_id INT NOT NULL,medicament_id INT NOT NULL,medicament_name VARCHAR(190) NOT NULL,quantity INT NOT NULL CHECK(quantity BETWEEN 1 AND 100),phone VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL,created_at BIGINT NOT NULL,expires_at BIGINT NOT NULL,FOREIGN KEY(client_id) REFERENCES client_users(id),FOREIGN KEY(medicament_id) REFERENCES medicament(id),INDEX reservations_expiry(status,expires_at),INDEX reservations_client(client_id,id),INDEX reservations_medicine(medicament_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS guard_pharmacies (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(190) NOT NULL,address VARCHAR(255) NOT NULL,commune VARCHAR(100) NOT NULL,phone VARCHAR(30) NOT NULL,start_at BIGINT NOT NULL,end_at BIGINT NOT NULL,active INT NOT NULL DEFAULT 1,is_olg INT NOT NULL DEFAULT 0,CHECK(end_at>start_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS pharmacies (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(190) NOT NULL,address VARCHAR(255) NOT NULL,commune VARCHAR(100) NOT NULL,phone VARCHAR(30) NOT NULL,identity_key VARCHAR(64) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pharmacy_guards (id INT PRIMARY KEY AUTO_INCREMENT,pharmacy_id INT NOT NULL,start_at BIGINT NOT NULL,end_at BIGINT NOT NULL,cancelled INTEGER NOT NULL DEFAULT 0,legacy_id INT UNIQUE, FOREIGN KEY(pharmacy_id) REFERENCES pharmacies(id),CHECK(end_at>start_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
